struct Order {   // copying id 3 throws
  int id;
  Order(int i) : id(i) {}
  Order(const Order& o) : id(o.id) {
    if (id == 3) throw std::runtime_error("");
  }
};
void add_all(std::vector<Order>& out,
             const std::vector<Order>& batch) {
  for (const Order& o : batch)
    out.push_back(o);
}
// out empty, batch holds ids 1..5

void add_all(std::vector<Order>& out,
             const std::vector<Order>& batch) {
  std::vector<Order> tmp = out;  // may throw
  for (const Order& o : batch)
    tmp.push_back(o);             // may throw
  out.swap(tmp);                  // no-throw
}  // throws: out unchanged
